/**
 * A parsed `pikos://` link.
 */

public enum DeepLink: Equatable, Hashable {
    
    case page(pageId: String
    )
    case view(viewId: SmartView
    )
    case calendar
    case quickAdd(prefill: String
    )
    case search(prefill: String
    )





}

#if compiler(>=6)
extension DeepLink: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDeepLink: FfiConverterRustBuffer {
    typealias SwiftType = DeepLink

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DeepLink {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .page(pageId: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .view(viewId: try FfiConverterTypeSmartView.read(from: &buf)
        )
        
        case 3: return .calendar
        
        case 4: return .quickAdd(prefill: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .search(prefill: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DeepLink, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .page(pageId):
