    public static func write(_ value: [Occurrence], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeOccurrence.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [Occurrence] {
        let len: Int32 = try readInt(&buf)
        var seq = [Occurrence]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeOccurrence.read(from: &buf))
        }
        return seq
    }
}

